import React, { useState } from "react";
import { useDispatch } from "react-redux";
import { getName } from "../redux/actions/index";
import styles from "../styles/search.css";
import { useHistory } from "react-router-dom";

export default function SearchBar() {
  const dispatch = useDispatch();
  const history = useHistory();
  const [name, setName] = useState("");
  const [id, setId] = useState("");

  function handleInputChange(e) {
    setName(e.target.value);
  }

  function handleSubmit(e) {
    e.preventDefault();
    if (name) {
      dispatch(getName(name)).then((response) => {
        if (response.payload.length > 0) {
          const dogId = response.payload[0].id;
          setId(dogId);
          history.push(`/dogs:${dogId}`);
        } else {
          // si no se encuentra ningún perro, no se redirige a nada
          setName("");
        }
      });
    }
  }

  function handleKeyDown(e) {
    if (e.keyCode === 32) {
      handleSubmit(e);
    }
  }
  
  return (
    <div>
      <form onSubmit={handleSubmit}>
        <input
          className={styles.searchInput}
          type="text"
          placeholder="Busca Perritos"
          value={name}
          onChange={handleInputChange}
          onKeyDown={handleKeyDown}
        />
        <button className={styles.lupita} type="submit">
          🔍
        </button>
      </form>
    </div>
  );
}
